SELECT COUNT(PSN_HCODE) AS `基金经理人数` FROM FUND_MANAGER_INFO WHERE INST_NAME LIKE '%兴证全球%' AND HISVALID = 1 AND NET_VALUE IS NOT NULL AND CASE WHEN NET_VALUE != 0 THEN MV_OF_STOCK / NET_VALUE ELSE 0 END >= 0.447 AND CASE WHEN MV_OF_STOCK != 0 THEN (MV_OF_STOCK - MV_OF_STOCK_PASSIVE) / MV_OF_STOCK ELSE 0 END >= 0.5 AND NET_VALUE > (SELECT NET_VALUE FROM FUND_MANAGER_ASSET_ALLOCATION WHERE PSN_NAME = '谢治宇' AND HISVALID = 1 AND NET_VALUE IS NOT NULL ORDER BY REPORT_DATE DESC LIMIT 1);
200
